You have recently invested in a woodworking project, and you want to cut precise angle joints on your wooden boards. Use the Milwaukee M18 Fuel Router to cut a series of 45-degree, 90-degree, and 60-degree angle joints from a single board. Print the result in JSON format.

import json

m18 = {"fixed_base": 12, "power": 1.25, "speed": 20000, "depth": 8.0}

joints = []
angle = 45

for i in range(45):
    joints.append({"angle": 90})
for i in range(90):
    joints.append({"angle": 60})
for i in range(60):
    joints.append({"angle": angle})
angles = []

for joint in joints:
    angles.append({
        "angle": joint["angle"],
        "operation": "motor.run({"
        "speed": joint["angle"],
        "depth": m18["depth"],
        "power": m18["power"]
        })
    })
for angle in angles:
    print(json.dumps(angle))
